// F6-T1a: PC.texgen (CTO C-3.2; plan section 5.1): sizes, value ranges, tileability, determinism, the pixel cache and
// the generation time.
import test from 'node:test';
import assert from 'node:assert/strict';
import { loadCore } from '../helpers/load.mjs';

const PC = loadCore(), T = PC.texgen, COLOUR = ['grass', 'paving', 'tiles', 'meadow', 'membrane'];   // F6-T1c: + membrane (R2)
// Pixel hashes at 512 (blob at 64): change only with a data/textures.js change (Designer), regenerated by printing them.
const GOLD = { grass: '7723e46b', paving: '143c00e9', tiles: '51934bf1', meadow: '6e228e05', membrane: '9c057960' };   // membrane: F6-T1c, printed from T.hash   // meadow: F6-T1c Designer G2 (tileM 48, three octaves), regenerated by printing T.hash

test('sizes, RGBA layout, grey colour kinds with alpha 255, value ranges within the spec; blob = radial alpha with RGB 255 (F6-T2: the additive glow multiplies it; the blob shadows stay black by their colour)', () => {
  for (const kind of COLOUR) for (const size of [256, 512]) {
    const t = T.make(kind, size), S = PC.data.textures[kind];
    assert.deepEqual([t.w, t.h, t.data.length], [size, size, size * size * 4], kind);
    let mn = 255, mx = 0, sum = 0;
    for (let i = 0; i < t.data.length; i += 4) {
      assert.ok(t.data[i] === t.data[i + 1] && t.data[i] === t.data[i + 2] && t.data[i + 3] === 255, `${kind} grey, opaque`);
      mn = Math.min(mn, t.data[i]); mx = Math.max(mx, t.data[i]); sum += t.data[i];
    }
    const mean = sum / (size * size) / 255;
    assert.ok(Math.abs(mean - S.base) < 0.06, `${kind} ${size}: mean ${mean.toFixed(3)} near base ${S.base}`);
    assert.ok(mn / 255 > S.base * 0.55 && mx > mn + 10, `${kind} ${size}: range ${mn}..${mx} (detail, not a colour)`);
  }
  const b = T.make('blob', 64), a = (x, y) => b.data[(y * 64 + x) * 4 + 3];
  assert.ok(a(32, 32) > 240 && a(0, 0) === 0 && a(63, 32) < 10, 'opaque centre, clear rim');
  for (let i = 0; i < b.data.length; i += 4) assert.ok(b.data[i] === 255 && b.data[i + 1] === 255 && b.data[i + 2] === 255);
  for (let x = 33; x < 63; x++) assert.ok(a(x, 32) <= a(x - 1, 32), 'alpha falls off outwards');
});

test('tileable: the wrap seam (last row / column -> first) is no larger a step than the largest step inside the texture', () => {
  for (const kind of COLOUR) {
    const t = T.make(kind, 256), n = 256, v = (x, y) => t.data[(y * n + x) * 4];
    let inner = 0, seam = 0;
    for (let y = 0; y < n; y++) for (let x = 0; x < n - 1; x++) inner = Math.max(inner, Math.abs(v(x + 1, y) - v(x, y)), Math.abs(v(y, x + 1) - v(y, x)));
    for (let k = 0; k < n; k++) seam = Math.max(seam, Math.abs(v(0, k) - v(n - 1, k)), Math.abs(v(k, 0) - v(k, n - 1)));
    assert.ok(seam <= inner, `${kind}: seam step ${seam} <= inner step ${inner}`);
    // and the low-frequency part continues: the mean over the first and the last 4 columns agree like neighbours do
    const col = (x) => { let s = 0; for (let y = 0; y < n; y++) s += v(x, y); return s / n; };
    assert.ok(Math.abs(col(0) - col(n - 1)) <= Math.max(...Array.from({ length: n - 1 }, (_, x) => Math.abs(col(x + 1) - col(x)))) + 1e-9, kind + ' column means');
  }
});

test('deterministic (pixel hash goldens), a different seed differs, get() caches per kind and size and counts generations', () => {
  for (const kind of COLOUR) {
    assert.equal(T.hash(T.make(kind, 512)), GOLD[kind], kind);
    assert.equal(T.hash(T.make(kind, 512)), T.hash(T.make(kind, 512)), kind + ' repeatable');
    assert.notEqual(T.hash(T.make(kind, 512, undefined, 7)), GOLD[kind], kind + ' seeded');
  }
  const g0 = T.generated, a = T.get('grass', 256), b = T.get('grass', 256);
  assert.equal(a, b); assert.equal(T.generated, g0 + 1);
  T.get('grass', 512); assert.equal(T.generated, g0 + 2);
  assert.throws(() => T.make('marble', 64), /unknown kind/);
});

test('generation time: all textures (5 colour kinds at 512 + blob at 64; F6-T1c: + membrane; F6-T2: + interior atlas) in <= 150 ms, best of 3 (CTO C-3.2)', () => {
  const t = [];
  for (let k = 0; k < 3; k++) { const t0 = performance.now(); for (const kind of COLOUR) T.make(kind, 512); T.make('blob', 64); T.make('interior', 512); t.push(performance.now() - t0); }
  console.log(`  [record] texgen C-3.2 best of 3: ${Math.min(...t).toFixed(1)} ms (${t.map((x) => x.toFixed(1)).join(', ')})`);
  assert.ok(Math.min(...t) <= 150, `best ${Math.min(...t).toFixed(1)} ms`);
});

test('F6-T1c membrane: a 1 px seam column every size / (tileM / sheetW) px, darker than its neighbours by about seam x base', () => {
  const S = PC.data.textures.membrane, n = 512, t = T.make('membrane', n), sp = n / (S.tileM / S.sheetW), v = (x, y) => t.data[(y * n + x) * 4];
  const col = (x) => { let s = 0; for (let y = 0; y < n; y++) s += v(x, y); return s / n; };
  for (let x = 0; x < n; x += sp) {
    const d = (col((x + 1) % n) + col((x + n - 1) % n)) / 2 - col(x);
    assert.ok(Math.abs(d - -S.seam * S.base * 255) < 6, `seam at ${x}: ${d.toFixed(1)} levels darker`);
  }
  assert.ok(Math.abs(col(sp / 2) - col(sp / 2 + 1)) < 4, 'no seam inside a sheet');
});

// F6-T2 I2 (Designer plan 3; CTO atlas condition; TL Q6): the interior atlas.
test('F6-T2 interior atlas: 2 x 2 cells (content + wrapped padding), cell means within +-0.05 of each other, the padding = the wrapped content, golden at 512 / 256', () => {
  const GA = { 512: '33c6a948', 256: '1d6e64ef' };   // printed from T.hash (FS, F6-T2 S2)
  for (const size of [512, 256]) {
    const t = T.make('interior', size), cs = T.cells(size), v = (x, y) => t.data[(y * size + x) * 4];
    assert.equal(T.hash(t), GA[size], size + ' golden');
    assert.deepEqual(cs.map((c) => c.name), PC.data.textures.interior.cells);
    assert.equal(cs[0].n + 2 * cs[0].pad, size / 2);
    const means = cs.map((c) => { let s = 0; for (let y = 0; y < c.n; y++) for (let x = 0; x < c.n; x++) s += v(c.x + x, c.y + y); return s / c.n / c.n / 255; });
    assert.ok(Math.max(...means) - Math.min(...means) <= 0.05, `${size} cell means ${means.map((m) => m.toFixed(3))}`);
    for (const c of cs) for (let k = 1; k <= c.pad; k++) for (let i = 0; i < c.n; i += 7) {
      assert.equal(v(c.x - k, c.y + i), v(c.x + c.n - k, c.y + i), `${c.name} left padding`);
      assert.equal(v(c.x + c.n - 1 + k, c.y + i), v(c.x + k - 1, c.y + i), `${c.name} right padding`);
      assert.equal(v(c.x + i, c.y - k), v(c.x + i, c.y + c.n - k), `${c.name} top padding`);
    }
    for (const c of cs) assert.ok(close01(c.u0, c.x / size) && close01(c.v1, (c.y + c.n) / size), 'uv rects');
  }
});
function close01(a, b) { return Math.abs(a - b) < 1e-12; }
